protocol.scriptContent:
// Tool Box Demo Protocol
// Demonstrates all available toolbox commands

const sampleName = params.sample_name;
const incubationMinutes = Number(params.incubation_minutes) || 5;
const notifyOnComplete = params.notify_on_complete === "true";

// Step 1: Show a welcome message
galago.showMessage(
  `Starting Tool Box demo for sample: ${sampleName}`,
  "Protocol Started"
);

// Step 2: Log a note for the run record
galago.note(`Sample "${sampleName}" loaded. Incubation set to ${incubationMinutes} min.`);

// Step 3: Assign a variable to track protocol state
galago.assignVariable("current_sample", sampleName);
galago.assignVariable("protocol_status", "in_progress");

// Step 4: Pause for user confirmation before starting
galago.pause("Confirm the sample is loaded, then click Continue.");

// Step 5: Prompt user for additional input via a form
galago.userForm("pre_run_checklist");

// Step 6: Run a timed incubation
galago.showMessage(
  `Beginning ${incubationMinutes}-minute incubation period.`,
  "Incubation"
);
galago.timer({
  minutes: incubationMinutes,
  seconds: 0,
  message: `Incubating sample: ${sampleName}`
});

// Step 7: Multi-step countdown with notes
const checkpoints = 3;
for (let i = 1; i <= checkpoints; i++) {
  galago.note(`Checkpoint ${i}/${checkpoints} reached.`);
  galago.timer({
    minutes: 0,
    seconds: 30,
    message: `Checkpoint ${i} — waiting 30 seconds`
  });
}

// Step 8: Pause for final review
galago.pause("Review results before completing the protocol.");

// Step 9: Record completion
galago.assignVariable("protocol_status", "completed");
galago.assignVariable("completed_at", new Date().toISOString());

// Step 10: Final message
if (notifyOnComplete) {
  galago.showMessage(
    `Protocol complete for sample: ${sampleName}. All ${checkpoints} checkpoints passed.`,
    "Protocol Complete"
  );
}

galago.note("Tool Box demo protocol finished successfully.");
